contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // try any amount; the function is payable to allow funding this contract before the call
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // record owner and contract balance before the call
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balBefore = address(c).balance;

        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read owner and balance after
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balAfter = address(c).balance;

        // General rule: owner never changes; if call did not revert, c.balance is zero.
        assert(ownerAfter == ownerBefore && (reverted || balAfter == 0));
    }

    receive() external payable {}
}

